return $input.all().map(item => {
  const data = item.json;

  // 1. Extract post URL and ID
  const postUrl = data.link || data.guid || data.id || '';

  // 2. Extract Image URL from the HTML content string
  const rawContent = data.content || '';
  const imgMatch = rawContent.match(/<img[^>]+src="([^">]+)"/);
  const imageUrl = imgMatch ? imgMatch[1] : '';

  // 3. Clean HTML from snippet while preserving <a> tags for links
  const rawText = data.contentSnippet || data.description || rawContent;
  const cleanSnippet = rawText.replace(/<\/?(?!\ba\b)[a-z0-9]+[^>]*>/ig, '').trim();

  // 4. Normalize categories
  let categoriesStr = '';
  if (Array.isArray(data.categories)) {
    categoriesStr = data.categories.map(c => typeof c === 'object' ? (c.name || c._ || '') : c).filter(Boolean).join(', ');
  } else if (typeof data.categories === 'string') {
    categoriesStr = data.categories;
  }

  // 5. Return clean structured data
  return {
    json: {
      title: (data.title || '').trim(),
      imageUrl: imageUrl,
      snippet: cleanSnippet,
      url: postUrl,
      categories: categoriesStr,
      publishedAt: data.isoDate || data.pubDate || ''
    }
  };
});
